import{_ as i,o as a,c as t,ae as s}from"./chunks/framework.B2ul6ABY.js";const u=JSON.parse('{"title":"Saivage v3 — Operator Runbook","description":"","frontmatter":{},"headers":[],"relativePath":"operator-runbook.md","filePath":"operator-runbook.md"}'),o={name:"operator-runbook.md"};function n(r,e,l,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="saivage-v3-—-operator-runbook" tabindex="-1">Saivage v3 — Operator Runbook <a class="header-anchor" href="#saivage-v3-—-operator-runbook" aria-label="Permalink to &quot;Saivage v3 — Operator Runbook&quot;">​</a></h1><p>This runbook is the current operator workflow guide for the Web Control Room, analyst control surface, and runtime recovery.</p><p>For the dedicated analyst operator guide covering the chat panel, shell policy, secret-path denylist, card-detail entry point, live attribution behavior, and focused web validation cadence, see <a href="/docs/analyst.html">Analyst Operator Guide</a>.</p><h2 id="_1-open-the-system-safely" tabindex="-1">1. Open the system safely <a class="header-anchor" href="#_1-open-the-system-safely" aria-label="Permalink to &quot;1. Open the system safely&quot;">​</a></h2><h3 id="public-surfaces" tabindex="-1">Public surfaces <a class="header-anchor" href="#public-surfaces" aria-label="Permalink to &quot;Public surfaces&quot;">​</a></h3><p>These remain available without API auth:</p><ul><li><code>/health</code></li><li><code>/</code></li><li><code>/docs/</code></li></ul><h3 id="protected-surfaces" tabindex="-1">Protected surfaces <a class="header-anchor" href="#protected-surfaces" aria-label="Permalink to &quot;Protected surfaces&quot;">​</a></h3><p>When <code>SAIVAGE_API_TOKEN</code> is configured, <code>/api/*</code> and <code>/ws</code> require the token.</p><p>In the Web Control Room:</p><ul><li>use the token control when API requests are unauthorized;</li><li>the Docs link remains usable even if API auth is missing.</li></ul><h2 id="_2-read-health-before-changing-state" tabindex="-1">2. Read health before changing state <a class="header-anchor" href="#_2-read-health-before-changing-state" aria-label="Permalink to &quot;2. Read health before changing state&quot;">​</a></h2><p>Quick checks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/runtime/status</span></span></code></pre></div><p>Interpret runtime states conservatively:</p><ul><li><code>unknown</code> — runtime state is missing or unreadable</li><li><code>idle</code> — no active dispatch is running</li><li><code>running</code> — active dispatch or goal work is in progress</li><li><code>paused</code> — new dispatch is paused</li><li><code>frozen</code> — operator freeze/handoff state is recorded</li><li><code>error</code> — degraded or failed runtime state needs attention</li></ul><h2 id="_3-use-the-web-control-room-by-workflow" tabindex="-1">3. Use the Web Control Room by workflow <a class="header-anchor" href="#_3-use-the-web-control-room-by-workflow" aria-label="Permalink to &quot;3. Use the Web Control Room by workflow&quot;">​</a></h2><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><p>Use Dashboard as the operating picture.</p><p>Look for:</p><ul><li>runtime summary and current state</li><li>queue and activity context where shown</li><li>analyst chat state</li><li>degraded or unauthorized banners</li><li>operator notifications and pending confirmations where shown</li></ul><p>Expected UI states include:</p><ul><li>connected/live</li><li>reconnecting</li><li>unauthorized</li><li>no-token</li><li>stale</li><li>degraded</li></ul><p>These states are intentional signals. They are not success states.</p><h3 id="cards-and-card-detail" tabindex="-1">Cards and card detail <a class="header-anchor" href="#cards-and-card-detail" aria-label="Permalink to &quot;Cards and card detail&quot;">​</a></h3><p>Use Cards to:</p><ul><li>browse by status or type;</li><li>open card detail;</li><li>inspect parent/child context where shown;</li><li>identify blocked, failed, or stale work.</li></ul><p>Use <strong>card detail</strong> as the supported operator inspection surface for:</p><ul><li>lifecycle explanation and completion/blocker state</li><li>parent/child hierarchy and evidence-card navigation</li><li>generated file metadata and preview eligibility</li><li>verification commands and process IDs</li><li>review result summary and evidence-card IDs</li><li>planner status and dispatch completion summaries</li><li>tool errors and parse-failure recovery</li><li><strong>card history</strong> via the <code>CardHistoryPanel</code></li><li><strong>Discuss with analyst</strong> one-click entry into a context-seeded analyst chat</li></ul><p>Do not use an empty queue alone as evidence that planning is complete.</p><h3 id="card-history" tabindex="-1">Card history <a class="header-anchor" href="#card-history" aria-label="Permalink to &quot;Card history&quot;">​</a></h3><p>Tracked card changes create a versioned history entry before the new card record is written. Tracked fields include operator-intent fields such as title, description, acceptance, instructions file, type/subtype, parentage, tags, priority/urgency/estimate, dependencies/relationships, assignment, artifacts, and attachments.</p><p>Use card history when you need to answer:</p><ul><li>what changed on a card;</li><li>who changed it;</li><li>whether a running agent may be stale;</li><li>which prior version the agent was likely following.</li></ul><p>Operator surfaces:</p><ul><li><strong>UI:</strong> card detail → <code>CardHistoryPanel</code></li><li><strong>REST:</strong> <code>GET /api/cards/:id/history</code>, <code>GET /api/cards/:id/history/:seq</code>, <code>GET /api/cards/:id/diff?from=&amp;to=</code></li><li><strong>Chat/tools:</strong> <code>list_card_history</code>, <code>get_card_history_entry</code>, <code>diff_card</code></li></ul><p>If an agent is still running after a tracked edit, expect a notification at its next safe point and do not trust a <code>done</code> result until the blocking notification is acknowledged when required.</p><h3 id="notifications-and-stale-work-warnings" tabindex="-1">Notifications and stale-work warnings <a class="header-anchor" href="#notifications-and-stale-work-warnings" aria-label="Permalink to &quot;Notifications and stale-work warnings&quot;">​</a></h3><p>Notifications exist for both operator surfaces and active agent sessions.</p><p>Primary triggers in the current system:</p><ul><li>tracked card mutations;</li><li>note creation;</li><li>runtime pause/resume/freeze/resume-from-freeze;</li><li>process-state notifications from future process controls are deferred in this cycle;</li><li>redacted config/provider changes when supported by the canonical write path.</li></ul><p>Severity rules you should remember:</p><ul><li><code>card_changed</code>: <code>block</code> when <code>acceptance</code>, <code>description</code>, <code>instructions_file</code>, or <code>depends_on</code> changed; otherwise <code>warn</code></li><li><code>note_added</code>: <code>warn</code> for <code>directive</code>, <code>block</code> for <code>escalation</code>, operator-only <code>info</code> for <code>comment</code>/<code>progress</code></li><li><code>runtime_state</code>: <code>block</code> for pause/freeze, <code>info</code> for resume/resume-from-freeze</li><li><code>process_state</code>: <code>warn</code></li><li><code>config_changed</code>: <code>info</code></li></ul><p>Operator surfaces:</p><ul><li><strong>UI:</strong> <code>NotificationsPanel</code>, <code>PendingConfirmationsPanel</code>, stale ribbon on active-card views</li><li><strong>REST:</strong> <code>GET /api/notifications</code>, <code>POST /api/notifications/:id/acknowledge</code></li><li><strong>Chat/tools:</strong> agent sessions use <code>acknowledge_notification</code>; operators acknowledge operator-surface notifications via UI or REST</li></ul><p>A stale ribbon or stale banner means a relevant notification arrived after the view last refreshed. Refresh first, then act.</p><h3 id="notes-directives-vs-escalations" tabindex="-1">Notes: directives vs escalations <a class="header-anchor" href="#notes-directives-vs-escalations" aria-label="Permalink to &quot;Notes: directives vs escalations&quot;">​</a></h3><p>Notes are not interchangeable with card edits.</p><p>Use a <strong>card edit</strong> when the objective, instructions, acceptance criteria, dependency graph, or ownership changed.</p><p>Use a <strong>note</strong> when the operator is adding runtime guidance or observations:</p><ul><li><code>comment</code> — operator/context note; operator notification only</li><li><code>progress</code> — progress/status note; operator notification only</li><li><code>directive</code> — present-tense steering for a running or queued agent; session notification severity <code>warn</code></li><li><code>escalation</code> — something is wrong or blocking; session notification severity <code>block</code></li></ul><p>A directive or escalation should be preferred over direct analyst→agent messaging. There is no direct analyst→running-agent chat lane in this design.</p><h3 id="card-detail-evidence-and-review-workflow" tabindex="-1">Card detail evidence and review workflow <a class="header-anchor" href="#card-detail-evidence-and-review-workflow" aria-label="Permalink to &quot;Card detail evidence and review workflow&quot;">​</a></h3><p>Read card detail in this order:</p><ol><li><strong>Lifecycle / Completion &amp; blockers</strong> — confirms whether the card is only marked done, actively blocked, failed, or independently reviewed.</li><li><strong>Hierarchy</strong> — shows ancestors and children so operators can inspect related work without raw state-file reads.</li><li><strong>Evidence &amp; generated files</strong> — shows aggregate evidence state: <ul><li><code>No operator-facing evidence is recorded yet</code></li><li><code>This terminal or blocked card has no operator-facing evidence recorded</code></li><li>missing files</li><li>blocked files with reasons</li><li>redacted evidence</li><li>parse-recovered / tool-error partial evidence</li></ul></li><li><strong>Verification commands</strong> — confirms pass/fail/unknown/timed-out command results.</li><li><strong>Review result</strong> — confirms whether a reviewer passed or failed the card and which evidence-card IDs were cited.</li><li><strong>Dispatch summary</strong> — confirms child dispatch outcomes where recorded.</li><li><strong>Card history</strong> — confirms whether the work was edited after the agent began.</li></ol><p>If the detail view shows <strong>This card detail may be stale</strong>, refresh the card before acting on evidence or completion state.</p><h3 id="analyst-secret-path-denylist" tabindex="-1">Analyst secret-path denylist <a class="header-anchor" href="#analyst-secret-path-denylist" aria-label="Permalink to &quot;Analyst secret-path denylist&quot;">​</a></h3><p>Analyst filesystem inspection uses one centralized secret-path policy. Requests that target secret-bearing paths are denied before file contents are read. The denylist covers auth profiles, env files, SSH keys, cloud credential locations, <code>.npmrc</code>, <code>.pypirc</code>, and similar secret material.</p><p>For directory listings, secret-bearing child entries are omitted entirely. The response includes <code>redacted_count</code>, and when one or more entries were suppressed the listing appends a single <code>&lt;redacted&gt;</code> summary row with the hidden count. Operators should treat that as an intentional safety boundary, not missing data.</p><p>For shell-command classification, commands that target denylisted secret-bearing paths are treated as unsafe. On analyst web chat they return preview-only confirmation semantics and do not execute immediately; commit requires <code>confirmed: true</code> plus the matching <code>preview_hash</code>. On Telegram, <code>run_shell_command</code> remains unavailable. See <a href="/docs/analyst.html">Analyst Operator Guide</a> for the full analyst shell and chat behavior.</p><h3 id="focused-analyst-web-validation" tabindex="-1">Focused analyst web validation <a class="header-anchor" href="#focused-analyst-web-validation" aria-label="Permalink to &quot;Focused analyst web validation&quot;">​</a></h3><p>When validating shipped analyst UI behavior from Waves L-M, run the focused suites with <strong>Vitest from <code>/work/saivage-v3/web</code></strong> (or the root wrapper that delegates there), not root Jest.</p><p>Relevant suites:</p><ul><li><code>analyst-chat-panel.test.ts</code></li><li><code>analyst-chat-store.test.ts</code></li><li><code>app-shell-analyst-drawer.test.ts</code></li><li><code>analyst-toaster.test.ts</code></li><li><code>card-detail-view.test.ts</code></li><li><code>card-history-panel-analyst-filter.test.ts</code></li><li><code>ws-store.test.ts</code></li></ul><p>Preferred commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /work/saivage-v3/web</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/analyst-chat-panel.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/analyst-chat-store.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/app-shell-analyst-drawer.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/analyst-toaster.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/card-detail-view.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/card-history-panel-analyst-filter.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/ws-store.test.ts</span></span></code></pre></div><p>or:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web:test:analyst-ui</span></span></code></pre></div><h3 id="generated-files-and-evidence" tabindex="-1">Generated files and evidence <a class="header-anchor" href="#generated-files-and-evidence" aria-label="Permalink to &quot;Generated files and evidence&quot;">​</a></h3><p>When reviewing generated files in card detail, expect one of these outcomes:</p><ul><li>previewable text file</li><li>redacted-only preview</li><li>blocked preview with a reason</li><li>missing file</li><li>binary or unpreviewable file</li><li>incomplete/no-evidence warning for a blocked/done/failed card</li></ul><p>Examples:</p><ul><li><code>.saivage/auth-profiles.json</code> is blocked</li><li><code>.saivage/saivage.json</code> is redacted-only</li><li>symlinks that resolve outside the project root are blocked or omitted from safe operator flows</li></ul><p>Card evidence and file APIs expose canonical project-relative paths only. Operators should not expect absolute workspace paths in successful file or generated-artifact responses.</p><h3 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h3><p>Use Agents to inspect planner, executor, reviewer, and analyst sessions.</p><p>Operators should be able to:</p><ul><li>find running or failed sessions</li><li>open a conversation</li><li>inspect linked cards, files, and process context</li><li>distinguish model/tool failure from successful completion</li><li>see when an operator update should have reached the session</li></ul><p>Conversation links may route to:</p><ul><li>card detail</li><li>Files view</li><li>Debug process context</li></ul><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><p>Use Files for contained project browsing and safe text preview.</p><p>Operators should expect explicit states for:</p><ul><li>unauthorized API access</li><li>blocked preview</li><li>not found</li><li>binary/unpreviewable content</li><li>redacted content</li></ul><p>A redacted preview is a successful preview with sensitive values removed by the server; it is not an error state.</p><p>Prefer Files or card-detail evidence links over raw filesystem inspection during routine operations.</p><h3 id="debug" tabindex="-1">Debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;Debug&quot;">​</a></h3><p>Use Debug for recovery and diagnostics:</p><ul><li>runtime state</li><li>Operator Control panel for runtime pause/resume and notes queue actions</li><li><code>NotificationsPanel</code> for operator-surface queue review and acknowledgement</li><li><code>PendingConfirmationsPanel</code> for preview-only rejected actions awaiting explicit confirmation</li><li>recent errors</li><li>event timeline</li><li>doctor checks</li><li>supervision and quarantine information</li><li>MCP status/tools</li><li>processes</li><li>control-action audit reads</li></ul><p>If the UI reports degraded, frozen, stale, or repeated agent failures, Debug is the first operator destination.</p><h2 id="_4-runtime-control-procedures" tabindex="-1">4. Runtime control procedures <a class="header-anchor" href="#_4-runtime-control-procedures" aria-label="Permalink to &quot;4. Runtime control procedures&quot;">​</a></h2><p>Pause/resume validation is shared across REST endpoints, CLI commands, web UI controls, and analyst tools. Server-hosted analyst chat/WebSocket controls receive the live <code>ActiveRuntime</code> when the server was started with runtime creation, so they have the same in-memory pause/resume effect as REST and web UI. Direct CLI or utility use without a live runtime falls back to canonical persisted-state control and emits an explicit notice when only disk state changed.</p><h3 id="pause-before-low-risk-maintenance" tabindex="-1">Pause before low-risk maintenance <a class="header-anchor" href="#pause-before-low-risk-maintenance" aria-label="Permalink to &quot;Pause before low-risk maintenance&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/runtime/pause</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><h3 id="resume-only-from-pause-or-idle" tabindex="-1">Resume only from pause or idle <a class="header-anchor" href="#resume-only-from-pause-or-idle" aria-label="Permalink to &quot;Resume only from pause or idle&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/runtime/resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><h3 id="freeze-before-handoff-or-disruptive-maintenance" tabindex="-1">Freeze before handoff or disruptive maintenance <a class="header-anchor" href="#freeze-before-handoff-or-disruptive-maintenance" aria-label="Permalink to &quot;Freeze before handoff or disruptive maintenance&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/runtime/freeze</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;reason&quot;:&quot;operator handoff&quot;}&#39;</span></span></code></pre></div><h3 id="resume-from-freeze" tabindex="-1">Resume from freeze <a class="header-anchor" href="#resume-from-freeze" aria-label="Permalink to &quot;Resume from freeze&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/runtime/resume-from-freeze</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><h3 id="resume-from-freeze-distinction" tabindex="-1">Resume-from-freeze distinction <a class="header-anchor" href="#resume-from-freeze-distinction" aria-label="Permalink to &quot;Resume-from-freeze distinction&quot;">​</a></h3><p>Do <strong>not</strong> use generic resume from <code>frozen</code> or <code>error</code> states.</p><p>Expected behavior:</p><ul><li>generic <code>resume</code> is for paused/idle dispatch state;</li><li><code>frozen</code> requires <code>resume-from-freeze</code>;</li><li>a rejected generic resume from <code>frozen</code> or <code>error</code> is an intentional safety response, not a bug.</li></ul><h2 id="_5-authorization-preview-and-audit" tabindex="-1">5. Authorization, preview, and audit <a class="header-anchor" href="#_5-authorization-preview-and-audit" aria-label="Permalink to &quot;5. Authorization, preview, and audit&quot;">​</a></h2><p>Mutating controls use a static authorization table keyed by <code>(actor, surface, safety_class) -&gt; allow | deny | preview_only</code>.</p><p>Current default policy summary:</p><ul><li>analyst on <code>web-chat</code>: <code>allow</code> for <code>read_only</code>/<code>low</code>, <code>preview_only</code> for <code>high</code> and <code>destructive</code>, <code>deny</code> for <code>deployment</code></li><li>analyst on <code>telegram</code>: <code>allow</code> for <code>read_only</code>/<code>low</code>, <code>preview_only</code> for <code>high</code>, <code>deny</code> for <code>destructive</code> and <code>deployment</code></li><li>user on <code>rest</code> and <code>cli</code>: more permissive by default, including <code>allow</code> for most <code>high</code>/<code>destructive</code> operations and <code>preview_only</code> for <code>deployment</code></li><li>runtime on <code>runtime</code>: internal canonical mutations are allowed except <code>deployment</code></li></ul><p>Operational rules:</p><ul><li><strong>deny</strong>: action fails and is audited as denied</li><li><strong>preview_only</strong>: action returns a preview and preview hash; commit requires <code>confirmed: true</code> plus the matching hash</li><li><strong>allow</strong>: action commits immediately via the canonical service</li></ul><p>For <code>run_shell_command</code>, note the surface-specific exception: analyst web chat returns preview-only flows for destructive commands, while Telegram does not expose the tool at all.</p><p>Customization:</p><ul><li>edit the static authz rule table in source (<code>src/agents/authz.ts</code>)</li><li>keep the table aligned across chat, REST, CLI, and web UI expectations</li><li>prefer changing the verdict table instead of adding one-off confirmation logic in individual tools/routes</li></ul><p>Every mutating call writes one control-action audit entry to <code>.saivage/runtime/control-actions.jsonl</code>.</p><p>Use audit reads when you need to answer:</p><ul><li>who changed state;</li><li>whether a preview was rejected vs confirmed;</li><li>whether authz denied a request;</li><li>whether a pause/freeze action came from chat, REST, CLI, runtime, or web UI. Process termination controls are deferred in this cycle.</li></ul><h2 id="_6-operator-notes-queue" tabindex="-1">6. Operator notes queue <a class="header-anchor" href="#_6-operator-notes-queue" aria-label="Permalink to &quot;6. Operator notes queue&quot;">​</a></h2><p>Unhandled notes are stored per card and indexed in <code>.saivage/notes/queue.json</code>.</p><p>Current backend behavior:</p><ul><li>queue reads/writes are schema-validated;</li><li><code>GET /api/notes</code> returns only reconciled unhandled notes with an attached <code>note</code> record;</li><li>stale queue entries that point at missing or handled notes are removed during reconciliation;</li><li>malformed persisted queue files return a controlled <code>500</code> instead of returning partial <code>note: undefined</code> rows;</li><li>note IDs are stable and sequence-based, not renumbered after deletion/handling.</li></ul><h2 id="_7-degraded-state-workflow" tabindex="-1">7. Degraded-state workflow <a class="header-anchor" href="#_7-degraded-state-workflow" aria-label="Permalink to &quot;7. Degraded-state workflow&quot;">​</a></h2><p>If runtime or UI state is degraded:</p><ol><li>Check <code>/health</code>.</li><li>Check <code>/api/runtime/status</code>.</li><li>Open Debug and inspect errors, timeline, doctor, supervision, processes, notifications, and control actions.</li><li>Open affected card detail or agent conversation for evidence and history.</li><li>Pause or freeze before manual intervention if state is still mutating.</li><li>Only then consider direct filesystem inspection.</li></ol><h2 id="_8-unauthorized-stale-and-offline-workflow" tabindex="-1">8. Unauthorized, stale, and offline workflow <a class="header-anchor" href="#_8-unauthorized-stale-and-offline-workflow" aria-label="Permalink to &quot;8. Unauthorized, stale, and offline workflow&quot;">​</a></h2><h3 id="unauthorized" tabindex="-1">Unauthorized <a class="header-anchor" href="#unauthorized" aria-label="Permalink to &quot;Unauthorized&quot;">​</a></h3><ul><li>verify <code>SAIVAGE_API_TOKEN</code> on the server;</li><li>re-enter the token in the UI;</li><li>confirm <code>/health</code> still works publicly;</li><li>confirm Docs remain reachable under <code>/docs/</code>.</li><li>in card detail, <code>Unauthorized</code> means the detail API could not be read; it does not mean the card has no evidence.</li></ul><h3 id="stale-or-reconnecting" tabindex="-1">Stale or reconnecting <a class="header-anchor" href="#stale-or-reconnecting" aria-label="Permalink to &quot;Stale or reconnecting&quot;">​</a></h3><ul><li>refresh the relevant view;</li><li>treat REST reload as authoritative after reconnect;</li><li>use Debug if stale or reconnecting state persists.</li><li>in card detail, a stale banner after a card-updated or notification event means status may have changed after the last evidence fetch.</li></ul><h3 id="offline" tabindex="-1">Offline <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;Offline&quot;">​</a></h3><ul><li>verify the server process and port binding;</li><li>verify docs and SPA serving separately from API runtime state;</li><li>use process inspection and logs if the server is up but runtime is not advancing.</li></ul>`,130)])])}const f=i(o,[["render",n]]);export{u as __pageData,f as default};
